"""The README's auto-generated block: key findings, the as-of date and the test count.

scripts/update_readme.py collects the numbers from the committed results and
calls render_block and replace_auto_block. Only the text between the two
markers is ever rewritten. Pure functions: tests/test_framework.py.
"""

from __future__ import annotations

import re

START = "<!-- AUTO:START -->"
END = "<!-- AUTO:END -->"


def replace_auto_block(text: str, block: str) -> str:
    """Replace what lies between START and END; everything outside is left byte for byte."""
    if text.count(START) != 1 or text.count(END) != 1:
        raise ValueError(f"README must contain exactly one {START} and one {END}")
    if text.index(START) > text.index(END):
        raise ValueError(f"{START} must come before {END}")
    head, rest = text.split(START)
    _, tail = rest.split(END)
    return f"{head}{START}\n{block.strip()}\n{END}{tail}"


def current_block(text: str) -> str:
    match = re.search(re.escape(START) + r"\n?(.*?)\n?" + re.escape(END), text, flags=re.S)
    return match.group(1) if match else ""


def render_block(facts: dict) -> str:
    """Markdown for the auto-block: a heading, an as-of line, one bullet per finding, the test count.

    `facts` = {"as_of": str, "findings": [str, ...], "n_tests": int}. Every finding sentence is
    built by src/wording.py from the numbers, so this function only arranges them.
    """
    bullets = "\n".join(f"- {line}" for line in facts.get("findings", []))
    return ("## Key findings\n\n"
            f"All numbers are from data to **{facts['as_of']}**. This block is regenerated by "
            "`scripts/update_readme.py` after every data refresh.\n\n"
            f"{bullets}\n\n"
            f"Automated tests: **{facts['n_tests']}** (pytest, offline), run on every push and before every "
            "data refresh is committed.")
